const targetLocation = $('Teleport Workers').first().json.buildLocation;
const tasks = $input.first().json;
const targetInfo = $('Webhook').first().json.body.targetInfo || {};
const sessionId = $('Webhook').first().json.body.sessionId || 'combat_session';
const COMBAT_RADIUS = 20;
const OFFSET_DISTANCE = 5;
const MIN_TEAMMATE_SPACING = 3;

const rallyPoint = {
  x: Math.floor(targetLocation.x),
  y: Math.floor(targetLocation.y),
  z: Math.floor(targetLocation.z)
};

const getCardinalDirection = (angleRadians) => {
  const normalized = ((angleRadians % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
  if (normalized < Math.PI / 4 || normalized >= 7 * Math.PI / 4) return 'east';
  if (normalized < 3 * Math.PI / 4) return 'north';
  if (normalized < 5 * Math.PI / 4) return 'west';
  return 'south';
};

const soldierNames = Object.keys(tasks).sort((a, b) => {
  const numA = parseInt(a.match(/\d+/)?.[0] || 0);
  const numB = parseInt(b.match(/\d+/)?.[0] || 0);
  return numA - numB;
});

const numSoldiers = soldierNames.length;
const updatedTasks = {};

soldierNames.forEach((soldierName, index) => {
  const angleRadians = (index / numSoldiers) * 2 * Math.PI;

  const startX = Math.floor(rallyPoint.x + Math.cos(angleRadians) * OFFSET_DISTANCE);
  const startZ = Math.floor(rallyPoint.z + Math.sin(angleRadians) * OFFSET_DISTANCE);
  const startY = rallyPoint.y;

  const cardinalDirection = getCardinalDirection(angleRadians);
  const otherSoldiers = soldierNames.filter(s => s !== soldierName);

  let task = tasks[soldierName];

  // Update TARGET field
  task = task.replace(
    /TARGET: undefined/,
    `TARGET: Iron Golem`
  );

  // Update POSITION
  const newPosition = `You start ${OFFSET_DISTANCE} blocks ${cardinalDirection} of the target at coordinates (${startX}, ${startY}, ${startZ}).`;
  task = task.replace(
    /POSITION:[\s\S]*?(?=\n\nEQUIPMENT:|EQUIPMENT:)/,
    `POSITION: ${newPosition}\n\n`
  );

  // Add combat zone info
  const combatZoneInfo = `
COMBAT ZONE:
- Your Start Position: (${startX}, ${startY}, ${startZ})
- Rally Point: (${rallyPoint.x}, ${rallyPoint.y}, ${rallyPoint.z})
- Max Chase Distance: ${COMBAT_RADIUS} blocks from rally point
- Your Approach: ${cardinalDirection} side

TEAMMATES: ${otherSoldiers.join(', ') || 'None'}
- Keep ${MIN_TEAMMATE_SPACING}+ blocks from teammates
- Stay on YOUR side of target`;

  if (task.includes('REMINDERS:')) {
    task = task.replace('REMINDERS:', `${combatZoneInfo}\n\nREMINDERS:`);
  } else {
    task += '\n' + combatZoneInfo;
  }

  updatedTasks[soldierName] = task;
});

return {
  tasks: updatedTasks,
  combatMetadata: {
    sessionId: sessionId,
    rallyPoint: rallyPoint,
    combatRadius: COMBAT_RADIUS,
    soldierCount: numSoldiers
  }
};

// Code Node: Generate Combat Tasks from Tactical Plan (NO CODE)

const plan = $('Webhook').first().json.body.combatPlan;
const soldierInstructions = plan.soldierInstructions;
const combatRequest = plan.combatRequest;
const targetInfo = plan.targetInfo;
const battlefieldAssessment = plan.battlefieldAssessment;

let coordinatedTasks = {};

soldierInstructions.forEach((soldier) => {
  const soldierName = soldier.soldierName;
  const objective = soldier.objective;
  const target = soldier.target;
  const positioning = soldier.positioning;
  const tactic = soldier.tactic;
  const healthThreshold = soldier.healthManagement.retreatThreshold;
  const combatDuration = soldier.combatDuration;
  const engagement = soldier.engagement;
  const equipment = soldier.equipment || {};
  const constraints = soldier.constraints || [];
  const instructionText = soldier.instructionText;

  // Format equipment
  const equipmentStr = [
    equipment.weapon ? `Weapon: ${equipment.weapon}` : null,
    equipment.armor ? `Armor: ${equipment.armor}` : null
  ].filter(Boolean).join(', ') || 'Whatever equipped';

  // Format constraints
  const constraintsStr = constraints
    .map(c => `- ${c}`)
    .join('\n');

  // Build task description (plain English, no code)
  coordinatedTasks[soldierName] = `COMBAT MISSION: ${combatRequest}

SOLDIER: ${soldierName}
ROLE: ${soldier.role.toUpperCase()}

OBJECTIVE: ${objective}

TARGET: ${target} (${targetInfo.targetType})

POSITION: Attack from ${positioning}

ENGAGEMENT TIMING: ${engagement.delay === 0 ? 'Engage immediately (no delay)' : `Wait ${engagement.delay}ms before engaging`}

EQUIPMENT: ${equipmentStr}

TACTIC: ${tactic}

BATTLEFIELD:
- Terrain: ${battlefieldAssessment.terrain}
- Hazards: ${battlefieldAssessment.hazards}
- Recommendations: ${battlefieldAssessment.recommendations}

INSTRUCTIONS:
${instructionText}

HEALTH & SAFETY:
- Retreat threshold: ${healthThreshold} HP (${Math.ceil(healthThreshold / 2)} hearts)
- Retreat action: ${soldier.healthManagement.action}
- Maximum combat duration: ${combatDuration} seconds

CONSTRAINTS:
${constraintsStr}

VICTORY CONDITION: ${plan.victoryCondition}
FAILURE CONDITION: ${plan.failureCondition}

SAFETY NOTES: ${plan.safetyNotes}`;
});

return coordinatedTasks;

const myWorkers =  $('Webhook').first().json.body.workers;
const enemyWorkers = $('Bot Workers List').first().json.workers;
